```tsx
// CheckoutPage.tsx
import React, { useMemo, useState } from "react";
import "./CheckoutPage.css";
import type { AddressErrors, CartItem, DeliveryAddress } from "./types";

interface CheckoutPageProps {
  items: CartItem[];
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress) => Promise<void> | void;
  shippingCost?: number;
  currency?: string;
}

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: "",
  line1: "",
  line2: "",
  city: "",
  postalCode: "",
  country: "",
  phone: "",
};

function formatPrice(amount: number, currency: string): string {
  return new Intl.NumberFormat(undefined, {
    style: "currency",
    currency,
  }).format(amount);
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) {
    errors.fullName = "Full name is required.";
  }
  if (!address.line1.trim()) {
    errors.line1 = "Street address is required.";
  }
  if (!address.city.trim()) {
    errors.city = "City is required.";
  }
  if (!address.postalCode.trim()) {
    errors.postalCode = "Postal code is required.";
  } else if (!/^[A-Za-z0-9\s-]{3,10}$/.test(address.postalCode.trim())) {
    errors.postalCode = "Enter a valid postal code.";
  }
  if (!address.country.trim()) {
    errors.country = "Country is required.";
  }
  if (!address.phone.trim()) {
    errors.phone = "Phone number is required.";
  } else if (!/^[+\d][\d\s-]{6,15}$/.test(address.phone.trim())) {
    errors.phone = "Enter a valid phone number.";
  }

  return errors;
}

export default function CheckoutPage({
  items,
  onBackToCart,
  onPay,
  shippingCost = 4.99,
  currency = "USD",
}: CheckoutPageProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [isPaying, setIsPaying] = useState(false);
  const [payError, setPayError] = useState<string | null>(null);

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0),
    [items]
  );
  const total = subtotal + (items.length > 0 ? shippingCost : 0);

  function handleFieldChange(field: keyof DeliveryAddress, value: string) {
    setAddress((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  }

  async function handlePay(e: React.FormEvent) {
    e.preventDefault();
    setPayError(null);

    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length > 0) {
      return;
    }
    if (items.length === 0) {
      setPayError("Your cart is empty.");
      return;
    }

    setIsPaying(true);
    try {
      await onPay(address);
    } catch (err) {
      setPayError(
        err instanceof Error ? err.message : "Payment failed. Please try again."
      );
    } finally {
      setIsPaying(false);
    }
  }

  return (
    <div className="checkout-page">
      <div className="checkout-header">
        <button
          type="button"
          className="back-link"
          onClick={onBackToCart}
          disabled={isPaying}
        >
          ← Back to cart
        </button>
        <h1>Checkout</h1>
      </div>

      <div className="checkout-layout">
        <section className="cart-summary" aria-label="Order summary">
          <h2>Order summary</h2>

          {items.length === 0 ? (
            <p className="empty-cart">Your cart is empty.</p>
          ) : (
            <ul className="cart-item-list">
              {items.map((item) => (
                <li key={item.id} className="cart-item">
                  <img
                    src={item.imageUrl}
                    alt={item.name}
                    className="cart-item-image"
                  />
                  <div className="cart-item-details">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-qty">Qty: {item.quantity}</span>
                  </div>
                  <span className="cart-item-price">
                    {formatPrice(item.unitPrice * item.quantity, currency)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <div className="totals">
            <div className="totals-row">
              <span>Subtotal</span>
              <span>{formatPrice(subtotal, currency)}</span>
            </div>
            <div className="totals-row">
              <span>Shipping</span>
              <span>
                {items.length > 0 ? formatPrice(shippingCost, currency) : "—"}
              </span>
            </div>
            <div className="totals-row totals-row-grand">
              <span>Total</span>
              <span>{formatPrice(total, currency)}</span>
            </div>
          </div>
        </section>

        <section className="address-section" aria-label="Delivery address">
          <h2>Delivery address</h2>
          <form className="address-form" onSubmit={handlePay} noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                value={address.fullName}
                onChange={(e) => handleFieldChange("fullName", e.target.value)}
                aria-invalid={Boolean(errors.fullName)}
                disabled={isPaying}
              />
              {errors.fullName && (
                <span className="field-error">{errors.fullName}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="line1">Street address</label>
              <input
                id="line1"
                type="text"
                value={address.line1}
                onChange={(e) => handleFieldChange("line1", e.target.value)}
                aria-invalid={Boolean(errors.line1)}
                disabled={isPaying}
              />
              {errors.line1 && <span className="field-error">{errors.line1}</span>}
            </div>

            <div className="form-field">
              <label htmlFor="line2">Apartment, suite, etc. (optional)</label>
              <input
                id="line2"
                type="text"
                value={address.line2}
                onChange={(e) => handleFieldChange("line2", e.target.value)}
                disabled={isPaying}
              />
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  value={address.city}
                  onChange={(e) => handleFieldChange("city", e.target.value)}
                  aria-invalid={Boolean(errors.city)}
                  disabled={isPaying}
                />
                {errors.city && <span className="field-error">{errors.city}</span>}
              </div>

              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  value={address.postalCode}
                  onChange={(e) =>
                    handleFieldChange("postalCode", e.target.value)
                  }
                  aria-invalid={Boolean(errors.postalCode)}
                  disabled={isPaying}
                />
                {errors.postalCode && (
                  <span className="field-error">{errors.postalCode}</span>
                )}
              </div>
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="country">Country</label>
                <input
                  id="country"
                  type="text"
                  value={address.country}
                  onChange={(e) => handleFieldChange("country", e.target.value)}
                  aria-invalid={Boolean(errors.country)}
                  disabled={isPaying}
                />
                {errors.country && (
                  <span className="field-error">{errors.country}</span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="phone">Phone number</label>
                <input
                  id="phone"
                  type="tel"
                  value={address.phone}
                  onChange={(e) => handleFieldChange("phone", e.target.value)}
                  aria-invalid={Boolean(errors.phone)}
                  disabled={isPaying}
                />
                {errors.phone && <span className="field-error">{errors.phone}</span>}
              </div>
            </div>

            {payError && <p className="pay-error" role="alert">{payError}</p>}

            <div className="checkout-actions">
              <button
                type="button"
                className="secondary-button"
                onClick={onBackToCart}
                disabled={isPaying}
              >
                Back to cart
              </button>
              <button
                type="submit"
                className="pay-button"
                disabled={isPaying || items.length === 0}
              >
                {isPaying ? "Processing…" : `Pay ${formatPrice(total, currency)}`}
              </button>
            </div>
          </form>
        </section>
      </div>
    </div>
  );
}
